 void NotesTab(){var p=Stack();p.Children.Add(Text("Мысли, долги, договорённости",17));p.Children.Add(Btn("+ Быстрая заметка",OpenQuickNote,true));p.Children.Add(Text("Запиши всё, что важно не забыть.",11,"Muted"));p.Children.Add(Text("ЗАГОЛОВОК",10,"Muted"));noteTitle=Input("Заголовок заметки");p.Children.Add(noteTitle);p.Children.Add(Text("ТЕКСТ ЗАМЕТКИ",10,"Muted"));noteBody=Input("Текст заметки");noteBody.MaxLength=10000;noteBody.AcceptsReturn=true;noteBody.TextWrapping=TextWrapping.Wrap;noteBody.VerticalScrollBarVisibility=ScrollBarVisibility.Auto;noteBody.Height=125;p.Children.Add(noteBody);p.Children.Add(Row(Btn("Сохранить заметку",SaveNote,true),Btn("Новая",ClearNote)));notesList=Stack();p.Children.Add(notesList);Tab("Заметки",p);}
 void ClearNote(){editingNoteId=null;noteTitle.Text="";noteBody.Text="";}
 void SaveNote(){var title=noteTitle.Text.Trim();var body=noteBody.Text.Trim();if(title.Length==0&&body.Length==0){Say("Заметка пустая. Добавь заголовок или текст.");return;}if(title.Length==0)title="Без названия";var note=data.Notes.FirstOrDefault(n=>n.Id==editingNoteId);bool added=note==null;if(added){if(data.Notes.Count>=10000){Say("Можно сохранить до 10000 заметок. Удали ненужные.");return;}note=new Memo{Id=Guid.NewGuid().ToString()};data.Notes.Add(note);}string oldTitle=note.Title,oldBody=note.Body;DateTime oldUpdated=note.Updated;note.Title=title;note.Body=body;note.Updated=DateTime.Now;if(!TrySave()){if(added)data.Notes.Remove(note);else{note.Title=oldTitle;note.Body=oldBody;note.Updated=oldUpdated;}return;}RenderNotes();ClearNote();Say("Заметка сохранена.");}
 void EditNote(Memo note){if(compact)SetCompact(false);if(designing)ShowDesign();OpenSectionDialog(2);editingNoteId=note.Id;noteTitle.Text=note.Title;noteBody.Text=note.Body;noteBody.Focus();Say("Редактирование заметки. Нажми «Сохранить заметку», когда закончишь.");}
