 class MiniItem{public string Kind,Id;public MiniItem(string kind,string id){Kind=kind;Id=id;}}
 List<MiniItem> MiniItems(){return data.Timers.Select(t=>new MiniItem("timer",t.Id)).Concat(data.Tasks.Select(t=>new MiniItem("task",t.Id))).Concat(data.Notes.Select(n=>new MiniItem("note",n.Id))).ToList();}
 void Pin(string kind,string id){data.MiniKind=kind;data.MiniId=id;miniSignature="";Save();SetCompact(true);}
 void CycleMini(int direction){var list=MiniItems();if(list.Count==0)return;int index=list.FindIndex(i=>i.Kind==data.MiniKind&&i.Id==data.MiniId);index=(Math.Max(0,index)+direction+list.Count)%list.Count;data.MiniKind=list[index].Kind;data.MiniId=list[index].Id;miniSignature="";Save();TickMini();}
 public static Rect FitExpandedWindow(Rect work,Point anchor,Size preferred){
  if(work.IsEmpty||work.Width<=0||work.Height<=0)throw new ArgumentException("The monitor work area must have a positive size.");
  double width=Math.Min(work.Width,Math.Max(Math.Min(410,work.Width),preferred.Width));
  double height=Math.Min(work.Height,Math.Max(Math.Min(350,work.Height),preferred.Height));
  double x=Double.IsNaN(anchor.X)?work.Left+(work.Width-width)/2:anchor.X;
  double y=Double.IsNaN(anchor.Y)?work.Top+(work.Height-height)/2:anchor.Y;
  return new Rect(Math.Max(work.Left,Math.Min(x,work.Right-width)),Math.Max(work.Top,Math.Min(y,work.Bottom-height)),width,height);
 }
 Rect CurrentWorkArea(){
  var handle=new System.Windows.Interop.WindowInteropHelper(this).Handle;
  var monitor=MonitorFromWindow(handle,2);var info=new CompanionMonitorInfo{Size=Marshal.SizeOf(typeof(CompanionMonitorInfo))};
  if(monitor==IntPtr.Zero||!GetMonitorInfo(monitor,ref info))return SystemParameters.WorkArea;
  var source=PresentationSource.FromVisual(this);Matrix transform=source==null?Matrix.Identity:source.CompositionTarget.TransformFromDevice;
  return new Rect(transform.Transform(new Point(info.Work.Left,info.Work.Top)),transform.Transform(new Point(info.Work.Right,info.Work.Bottom)));
 }
 void RestoreExpandedBounds(){
  // Read the monitor while the native window still has its miniature bounds.
  var work=CurrentWorkArea();var fit=FitExpandedWindow(work,new Point(base.Left,base.Top),new Size(normalWidth,normalHeight));
  if(WindowState!=WindowState.Normal)WindowState=WindowState.Normal;
  MinWidth=Math.Min(410,work.Width);MinHeight=Math.Min(350,work.Height);
  base.Left=fit.Left;base.Top=fit.Top;Width=fit.Width;Height=fit.Height;
 }
 [StructLayout(LayoutKind.Sequential)]struct CompanionMonitorRect{public int Left,Top,Right,Bottom;}
 [StructLayout(LayoutKind.Sequential)]struct CompanionMonitorInfo{public int Size;public CompanionMonitorRect Monitor,Work;public uint Flags;}
 [DllImport("user32.dll")]static extern IntPtr MonitorFromWindow(IntPtr hwnd,uint flags);
 [DllImport("user32.dll",CharSet=CharSet.Auto)]static extern bool GetMonitorInfo(IntPtr monitor,ref CompanionMonitorInfo info);
 void SetCompact(bool value){if(value){CloseCardGames();CloseHelp();CloseArcade();CloseSectionDialog(false,true);}if(value&&sectionReorderEditing)SetSectionReorder(false);if(compact==value){TickMini();return;}compact=value;if(value){normalWidth=Width;normalHeight=Height;normalLayout.Visibility=Visibility.Collapsed;miniLayout.Visibility=Visibility.Visible;MinWidth=64;MinHeight=28;ResizeMode=ResizeMode.CanResize;frame.CornerRadius=new CornerRadius(7);HideMiniDock(true);miniSignature="";TickMini();}else{HideMiniDock(true);miniLayout.Visibility=Visibility.Collapsed;normalLayout.Visibility=Visibility.Visible;RestoreExpandedBounds();ResizeMode=ResizeMode.CanResizeWithGrip;frame.CornerRadius=new CornerRadius(15);}Animate(compact?(UIElement)miniBody:normalLayout,1,200);}
 void TickMini(){if(miniBody==null)return;var list=MiniItems();if(!list.Any(i=>i.Kind==data.MiniKind&&i.Id==data.MiniId)&&list.Count>0){var first=list[0];data.MiniKind=first.Kind;data.MiniId=first.Id;miniSignature="";}
  var timer=data.MiniKind=="timer"?data.Timers.FirstOrDefault(t=>t.Id==data.MiniId):null;var task=data.MiniKind=="task"?data.Tasks.FirstOrDefault(t=>t.Id==data.MiniId):null;var note=data.MiniKind=="note"?data.Notes.FirstOrDefault(n=>n.Id==data.MiniId):null;string signature=timer!=null?"t"+timer.Id+timer.Title+(timer.End==0)+ (Left(timer)<=0):task!=null?"d"+task.Id+task.Title+task.Done:note!=null?"n"+note.Id+note.Title+note.Body:"empty";
  bool contentChanged=signature!=miniSignature;if(contentChanged){miniSignature=signature;miniBody.Children.Clear();miniActions.Children.Clear();miniClock=null;
   if(timer!=null){miniBody.Children.Add(Text(timer.Title,15));miniClock=Text("",43,"Accent");miniClock.FontFamily=new FontFamily("Consolas");miniClock.Margin=new Thickness(0);miniBody.Children.Add(miniClock);miniActions.Children.Add(Btn(Left(timer)<=0?"Ещё раз":timer.End==0?"Продолжить":"Пауза",()=>{if(Left(timer)<=0){timer.End=Now+(long)timer.Duration;timer.Remaining=timer.Duration;timer.Alerted=false;}else if(timer.End>0){timer.Remaining=Left(timer);timer.End=0;}else{timer.End=Now+(long)timer.Remaining;timer.Alerted=false;}Save();RenderTimers();miniSignature="";TickMini();}));}
   else if(task!=null){var text=Text(task.Title,20,task.Done?"Muted":"Text");if(task.Done)text.TextDecorations=TextDecorations.Strikethrough;miniBody.Children.Add(text);miniActions.Children.Add(Btn(task.Done?"Вернуть в дела":"Готово",()=>{task.Done=!task.Done;Save();RenderTasks();miniSignature="";TickMini();}));}
   else if(note!=null){miniBody.Children.Add(Text(note.Title,15));var body=Text(note.Body,14);body.Margin=new Thickness(0);miniBody.Children.Add(body);miniActions.Children.Add(Btn("Изменить заметку",()=>EditNote(note)));}
   else miniBody.Children.Add(Text("Добавь таймер, дело\nили заметку",17,"Muted"));
  }if(timer!=null&&miniClock!=null)miniClock.Text=Left(timer)<=0?"ГОТОВО":Clock(Left(timer));if(contentChanged&&compact)Dispatcher.BeginInvoke(DispatcherPriority.Loaded,(Action)(()=>{if(compact){miniBody.InvalidateMeasure();miniLayout.UpdateLayout();SizeMiniToContent();}}));
 }
 void AddMiniMenu(ContextMenu menu,string title,Action action){var item=new MenuItem{Header=title};item.Click+=(s,e)=>action();menu.Items.Add(item);}
 void ScaleMini(double factor){Width=Math.Max(Math.Max(MinWidth,MinHeight*miniAspect),Width*factor);Height=Width/miniAspect;data.MiniWidth=Width;Save();}
 void AddMiniGrip(int edge,HorizontalAlignment horizontal,VerticalAlignment vertical,Cursor cursor){var grip=new Thumb{HorizontalAlignment=horizontal,VerticalAlignment=vertical,Cursor=cursor,Template=(ControlTemplate)XamlReader.Parse(@"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='Thumb'><Border Background='#01000000'/></ControlTemplate>")};if(horizontal!=HorizontalAlignment.Stretch)grip.Width=6;if(vertical!=VerticalAlignment.Stretch)grip.Height=6;double startWidth=0,startHeight=0,startLeft=0,startTop=0,totalX=0,totalY=0;grip.DragStarted+=(s,e)=>{startWidth=Width;startHeight=Height;startLeft=base.Left;startTop=base.Top;totalX=0;totalY=0;};grip.DragDelta+=(s,e)=>{totalX+=e.HorizontalChange;totalY+=e.VerticalChange;bool fromLeft=edge==1||edge==4||edge==7,fromTop=edge==3||edge==4||edge==5;var fit=FitMiniDimensions(startWidth+(fromLeft?-totalX:totalX),startHeight+(fromTop?-totalY:totalY),edge,miniAspect,MinWidth,MinHeight);Width=fit.Width;Height=fit.Height;if(fromLeft)base.Left=startLeft+startWidth-Width;if(fromTop)base.Top=startTop+startHeight-Height;};grip.DragCompleted+=(s,e)=>{data.MiniWidth=Width;Save();};miniLayout.Children.Add(grip);}
 void SizeMiniToContent(){if(!compact||miniBody==null)return;miniBody.Width=Double.NaN;miniBody.Measure(new Size(300,Double.PositiveInfinity));miniBody.Width=Math.Max(64,Math.Min(300,miniBody.DesiredSize.Width));miniBody.Measure(new Size(miniBody.Width,Double.PositiveInfinity));double naturalWidth=miniBody.Width+18,naturalHeight=Math.Max(30,miniBody.DesiredSize.Height+18);miniAspect=naturalWidth/naturalHeight;double width=data.MiniWidth>=64&&data.MiniWidth<=5000?data.MiniWidth:naturalWidth;Width=Math.Max(Math.Max(MinWidth,MinHeight*miniAspect),width);Height=Width/miniAspect;}
 bool HandleMiniResize(int message,IntPtr w,IntPtr l,out IntPtr result){result=IntPtr.Zero;return false;}
 public struct MiniSize{public int Width,Height;public MiniSize(int width,int height){Width=width;Height=height;}}
 public static MiniSize FitMiniDimensions(double width,double height,int edge,double aspect,double minWidth,double minHeight){double fitWidth=(edge==3||edge==6)?height*aspect:width;fitWidth=Math.Max(Math.Max(minWidth,minHeight*aspect),fitWidth);return new MiniSize((int)Math.Round(fitWidth),(int)Math.Round(fitWidth/aspect));}
